export function decodeString(encoded        )         {
let i=0;function parse()       {let out="";while(i<encoded.length&&encoded[i]!=="]"){if(encoded[i]>="0"&&encoded[i]<="9"){let n=0;while(encoded[i]>="0"&&encoded[i]<="9")n=n*10+Number(encoded[i++]);i++;const part=parse();i++;out+=part.repeat(n);}else out+=encoded[i++];}return out;}return parse();
}

